    periodId: "egypte_nouvel",
    civName: "Égypte : Nouvel Empire",
    century: "Fin de la XVIIIe dynastie (vers -1320 av. J.-C. / règne de Toutânkhamon)",
    centuryDisplay: "XIVe s. av. J.-C.",
    centuryNumeric: -1320,
    domain: "sculpture_statuaire",
