    domain: "sculpture_statuaire",
    artifactType: "Statuaire royale & divine (ronde-bosse)",
    title: "Statue marchante monumentale de Ramsès II au Pschent et némès en granit rose (Tanis, Musée du Caire)",
    site: "Temple d'Amon (Tanis)",
    originSite: "Tanis",
    locationType: "museum",
